// renew renews sub once for every period that has ended by now, so a late renewal job catches up on each missed period.
func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return store.ErrNotFound
	}
	for !sub.CurrentPeriodEnd.After(now) {
		if sub.CancelAtPeriodEnd {
			end := sub.CurrentPeriodEnd
			canceled, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
				x.Status, x.CanceledAt = store.Canceled, &end
				return nil
			})
			if err == nil {
				s.publish(ctx, sub.OrgID, "subscription.canceled", canceled)
			}
			return err
		}
		var err error
		if sub, err = s.renewPeriod(ctx, sub, plan); err != nil {
			return err
		}
	}
	return nil
}

// renewPeriod starts the period that follows sub's current one, at the moment that one ends, and invoices it.
func (s *Service) renewPeriod(ctx context.Context, sub store.Subscription, plan store.Plan) (store.Subscription, error) {
	start := sub.CurrentPeriodEnd
	end := billing.NextBoundary(anchor(sub), plan.Interval, start)
	paid := true
	var err error
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
	case plan.UsageType == store.Licensed:
		paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
	}
	if err != nil {
		return sub, err
	}
	sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
		if paid {
			x.Status = store.Active
		} else {
			x.Status = store.PastDue
		}
		return nil
	})
	if err != nil {
		return sub, err
	}
	s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	return sub, nil
}

// anchor returns the start of a subscription's first paid period, from which its billing periods are counted: the end of its
// trial for one that started with a trial, else the start of the subscription.
func anchor(sub store.Subscription) time.Time {
	if sub.TrialEnd != nil {
		return *sub.TrialEnd
	}
	return sub.StartedAt
}

