func TestLateRenewalStartsAtThePreviousPeriodEnd(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	e.Clock.Set(time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC))
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	feb28 := time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC)
	if !sub.CurrentPeriodEnd.Equal(feb28) {
		t.Fatalf("first period ends %v, want %v", sub.CurrentPeriodEnd, feb28)
	}
	e.Clock.Set(time.Date(2026, 3, 9, 4, 0, 0, 0, time.UTC)) // the job runs over a week late
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
