1	// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
2	// renewing them when a billing period ends.
3	package subscriptions
4	
5	import (
6		"context"
7		"errors"
8		"fmt"
9		"time"
10	
11		"example.com/tally/internal/billing"
12		"example.com/tally/internal/clock"
13		"example.com/tally/internal/payments"
14		"example.com/tally/internal/store"
15	)
16	
17	// Errors.
18	var (
19		ErrPlanInactive = errors.New("the plan is not active")
20		ErrCanceled     = errors.New("the subscription is canceled")
21	)
22	
23	// Service runs subscriptions.
24	type Service struct {
25		Store     *store.Store
26		Payments  *payments.Service
27		Clock     clock.Clock
28		Publisher payments.Publisher // nil: no events
29	}
30	
31	// CreateInput is a new subscription.
32	type CreateInput struct {
33		CustomerID      string
34		PlanID          string
35		Quantity        int // 0 means 1
36		DiscountPercent int
37	}
38	
39	// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
40	// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
41	// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
42	func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
43		plan, ok := s.Store.Plan(orgID, in.PlanID)
44		if !ok {
45			return store.Subscription{}, store.ErrNotFound
46		}
47		if !plan.Active {
48			return store.Subscription{}, ErrPlanInactive
49		}
50		if in.Quantity == 0 {
51			in.Quantity = 1
52		}
53		now := s.Clock.Now()
54		sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
55			StartedAt: now, CurrentPeriodStart: now}
56		if plan.TrialDays > 0 {
57			end := now.AddDate(0, 0, plan.TrialDays)
58			sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
59		} else {
60			sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
61		}
62		sub, err := s.Store.CreateSubscription(sub, now)
63		if err != nil {
64			return store.Subscription{}, err
65		}
66		s.publish(ctx, orgID, "subscription.created", sub)
67		if sub.Status == store.Active && plan.UsageType == store.Licensed {
68			paid, err := s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
69			if err != nil {
70				return sub, err
71			}
72			if !paid {
73				if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
74					return sub, err
75				}
76			}
77		}
78		return sub, nil
79	}
80	
81	// UpdateInput changes a subscription; nil fields stay as they are.
82	type UpdateInput struct {
83		PlanID   *string
84		Quantity *int
85	}
86	
87	// Update changes a subscription's plan or quantity. The change applies at once and is billed from the next period on.
88	func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
89		if in.PlanID != nil {
90			p, ok := s.Store.Plan(orgID, *in.PlanID)
91			if !ok {
92				return store.Subscription{}, store.ErrNotFound
93			}
94			if !p.Active {
95				return store.Subscription{}, ErrPlanInactive
96			}
97		}
98		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
99			if sub.Status == store.Canceled {
100				return ErrCanceled
101			}
102			if in.PlanID != nil {
103				sub.PlanID = *in.PlanID
104			}
105			if in.Quantity != nil {
106				sub.Quantity = *in.Quantity
107			}
108			return nil
109		})
110		if err != nil {
111			return store.Subscription{}, err
112		}
113		s.publish(ctx, orgID, "subscription.updated", sub)
114		return sub, nil
115	}
116	
117	// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
118	// subscription changes nothing.
119	func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
120		now := s.Clock.Now()
121		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
122			if sub.Status == store.Canceled {
123				return nil
124			}
125			if atPeriodEnd {
126				sub.CancelAtPeriodEnd = true
127				return nil
128			}
129			sub.Status, sub.CanceledAt = store.Canceled, &now
130			return nil
131		})
132		if err != nil {
133			return store.Subscription{}, err
134		}
135		if sub.Status == store.Canceled {
136			s.publish(ctx, orgID, "subscription.canceled", sub)
137		} else {
138			s.publish(ctx, orgID, "subscription.updated", sub)
139		}
140		return sub, nil
141	}
142	
143	// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
144	// at the end of its period is canceled. Otherwise each period that has ended, in order, is followed by the next one, which
145	// starts where the previous one ended and is invoiced: a licensed plan bills the new period in advance, a metered plan bills
146	// the usage of the period that ended. A subscription several periods behind gets one invoice per missed period. A declined
147	// charge makes the subscription past due. RenewDue returns how many subscriptions it renewed or canceled.
148	func (s *Service) RenewDue(ctx context.Context) (int, error) {
149		now := s.Clock.Now()
150		n := 0
151		for _, sub := range s.Store.DueSubscriptions(now) {
152			if err := ctx.Err(); err != nil {
153				return n, err
154			}
155			if err := s.renew(ctx, sub, now); err != nil {
156				return n, fmt.Errorf("renew %s: %w", sub.ID, err)
157			}
158			n++
159		}
160		return n, nil
161	}
162	
163	// renew renews sub once for every period that has ended by now, so a late renewal job catches up on each missed period.
164	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
165		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
166		if !ok {
167			return store.ErrNotFound
168		}
169		for !sub.CurrentPeriodEnd.After(now) {
170			if sub.CancelAtPeriodEnd {
171				end := sub.CurrentPeriodEnd
172				canceled, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
173					x.Status, x.CanceledAt = store.Canceled, &end
174					return nil
175				})
176				if err == nil {
177					s.publish(ctx, sub.OrgID, "subscription.canceled", canceled)
178				}
179				return err
180			}
181			var err error
182			if sub, err = s.renewPeriod(ctx, sub, plan); err != nil {
183				return err
184			}
185		}
186		return nil
187	}
188	
189	// renewPeriod starts the period that follows sub's current one, at the moment that one ends, and invoices it.
190	func (s *Service) renewPeriod(ctx context.Context, sub store.Subscription, plan store.Plan) (store.Subscription, error) {
191		start := sub.CurrentPeriodEnd
192		end := billing.NextBoundary(anchor(sub), plan.Interval, start)
193		paid := true
194		var err error
195		switch {
196		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
197			paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
198		case plan.UsageType == store.Licensed:
199			paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
200		}
201		if err != nil {
202			return sub, err
203		}
204		sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
205			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
206			if paid {
207				x.Status = store.Active
208			} else {
209				x.Status = store.PastDue
210			}
211			return nil
212		})
213		if err != nil {
214			return sub, err
215		}
216		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
217		return sub, nil
218	}
219	
220	// anchor returns the start of a subscription's first paid period, from which its billing periods are counted: the end of its
221	// trial for one that started with a trial, else the start of the subscription.
222	func anchor(sub store.Subscription) time.Time {
223		if sub.TrialEnd != nil {
224			return *sub.TrialEnd
225		}
226		return sub.StartedAt
227	}
228	
229	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
230	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
231	// payment method stays open and counts as paid here (it is paid by hand).
232	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
233		var lines []store.Line
234		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
235		switch plan.UsageType {
236		case store.Licensed:
237			if plan.UnitAmount > 0 {
238				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
239			}
240		case store.Metered:
241			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
242				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
243			}
244		}
245		ps, pe := start, end
246		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
247			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
248		if err != nil {
249			return false, err
250		}
251		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
252		_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
253		var decline *payments.DeclineError
254		switch {
255		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
256			return true, nil
257		case errors.As(err, &decline):
258			return false, nil
259		default:
260			return false, err
261		}
262	}
263	
264	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
265		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
266			x.Status = st
267			return nil
268		})
269		if err == nil {
270			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
271		}
272		return sub, err
273	}
274	
275	func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
276		if s.Publisher != nil {
277			_ = s.Publisher.Publish(ctx, orgID, typ, data)
278		}
279	}
